impl ShapeClip {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("xml:");
        uo_codec::dump::utf16(out, &self.xml);
        out.push_str(",rels:");
        out.push('[');
        for (i0, e0) in self.rels.iter().enumerate() {
            if i0 > 0 { out.push(','); }
            e0.dump(out, t);
        }
        out.push(']');
        out.push_str(",text:");
        uo_codec::dump::utf16(out, &self.text);
        out.push_str(",source_id:");
        uo_codec::dump::f64(out, self.source_id);
        out.push_str(",slide_path:");
        uo_codec::dump::utf16(out, &self.slide_path);
        out.push('}');
    }
}

impl ShapeClip {
    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        Self {
            xml: rng.utf16(6),
            rels: { let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| ClipRel::random(rng, b, depth + 1)).collect::<Vec<_>>() },
            text: rng.utf16(6),
            source_id: rng.f64_edge(),
            slide_path: rng.utf16(6),
        }
    }
}

